option.value:
package static_analysis_engine

type Finding struct {
	RuleID      string `json:"rule_id"`
	Message     string `json:"message"`
	FilePath    string `json:"file_path"`
	Line        int    `json:"line"`
	Severity    string `json:"severity"`
	Snippet     string `json:"snippet"`
}

// Severity constants for findings
const (
	SeverityInfo     = "info"
	SeverityLow      = "low"
	SeverityMedium   = "medium"
	SeverityHigh     = "high"
	SeverityCritical = "critical"
)

// AllSeverities lists all supported severity values (useful for validation/iteration)
var AllSeverities = []string{
	SeverityInfo,
	SeverityLow,
	SeverityMedium,
	SeverityHigh,
	SeverityCritical,
}

// IsValidSeverity returns true if the provided severity is one of the supported constants.
func IsValidSeverity(s string) bool {
	switch s {
	case SeverityInfo, SeverityLow, SeverityMedium, SeverityHigh, SeverityCritical:
		return true
	default:
		return false
	}
}

